PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?grandfather ?grandfatherName WHERE {
  dbr:William_IV,_Count_of_Ponthieu dbp:father dbr:John_I,_Count_of_Ponthieu .
  dbr:John_I,_Count_of_Ponthieu dbp:father ?grandfather .
  OPTIONAL { ?grandfather rdfs:label ?grandfatherName .
             FILTER (lang(?grandfatherName) = "en") }
}
LIMIT 100

